import sys

class Student:
    def __init__(self, name):
        self.name = name
        self.marks_list = []
        self.average = 0.0
        self.grade = ''

    def add_marks(self, marks):
        self.marks_list.append(marks)
        print("Marks added")

    def calculate_grade(self):
        if self.marks_list:
            self.average = sum(self.marks_list) / len(self.marks_list)
        else:
            self.average = 0.0

        if self.average >= 90:
            self.grade = 'A'
        elif self.average >= 80:
            self.grade = 'B'
        elif self.average >= 70:
            self.grade = 'C'
        elif self.average >= 60:
            self.grade = 'D'
        else:
            self.grade = 'F'
        print("Grade calculated")

    def display(self):
        print(f"{self.name}: {self.average} - {self.grade}")


def main():
    students = {}

    n = int(sys.stdin.readline().strip())

    for _ in range(n):
        line = sys.stdin.readline().strip()
        if not line:
            continue

        parts = line.split()
        operation = parts[0].lower()

        if operation == 'add':
            name = parts[1]
            marks = float(parts[2])
            if name not in students:
                students[name] = Student(name)
            students[name].add_marks(marks)

        elif operation == 'calculate':
            name = parts[1]
            if name not in students:
                students[name] = Student(name)
            students[name].calculate_grade()

        elif operation == 'display':
            name = parts[1]
            if name not in students:
                students[name] = Student(name)
            students[name].display()


if __name__ == "__main__":
    main()
